section.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://faion.net/schemas/freelancer-payment-chase-script-library.json",
  "title": "Payment chase ladder for one invoice",
  "type": "object",
  "required": ["invoice", "parties", "contract", "rungs", "status", "send_log", "renewal_terms_change"],
  "additionalProperties": false,
  "properties": {
    "invoice": {
      "type": "object",
      "required": ["invoice_id", "amount", "currency", "invoice_date", "due_date", "payment_terms_clause_id", "invoice_link"],
      "properties": {
        "invoice_id": {"type": "string", "minLength": 1},
        "amount": {"type": "number", "exclusiveMinimum": 0},
        "currency": {"type": "string", "pattern": "^[A-Z]{3}$"},
        "invoice_date": {"type": "string", "pattern": "^\\d{4}-\\d{2}-\\d{2}$"},
        "due_date": {"type": "string", "pattern": "^\\d{4}-\\d{2}-\\d{2}$"},
        "payment_terms_clause_id": {"type": "string", "minLength": 1},
        "invoice_link": {"type": "string", "minLength": 1}
      }
    },
    "parties": {
      "type": "object",
      "required": ["freelancer", "client"],
      "properties": {
        "freelancer": {
          "type": "object",
          "required": ["legal_name", "address"],
          "properties": {
            "legal_name": {"type": "string", "minLength": 3},
            "address": {"type": "string", "minLength": 10}
          }
        },
        "client": {
          "type": "object",
          "required": ["legal_name", "address", "sponsor_contact", "finance_contact"],
          "properties": {
            "legal_name": {"type": "string", "minLength": 3},
            "address": {"type": "string", "minLength": 10},
            "sponsor_contact": {"type": "string", "pattern": "^[^@\\s]+@[^@\\s]+$"},
            "finance_contact": {"type": "string", "pattern": "^[^@\\s]+@[^@\\s]+$"}
          }
        }
      }
    },
    "contract": {
      "type": "object",
      "required": ["written_notice_channel", "late_payment_basis", "legal_handoff_contact"],
      "properties": {
        "written_notice_channel": {"type": "string", "enum": ["email", "registered_post", "email_and_registered_post", "courier"]},
        "late_payment_basis": {
          "type": "object",
          "required": ["kind"],
          "properties": {
            "kind": {"type": "string", "enum": ["contract_clause", "statute", "none"]},
            "reference": {"type": "string", "minLength": 5},
            "rate": {"type": "string", "minLength": 2},
            "fixed_fee": {"type": "number", "minimum": 0}
          },
          "if": {"properties": {"kind": {"enum": ["contract_clause", "statute"]}}},
          "then": {"required": ["reference", "rate"]}
        },
        "legal_handoff_contact": {"type": "string", "minLength": 3}
      }
    },
    "rungs": {
      "type": "array",
      "minItems": 3,
      "maxItems": 3,
      "items": {
        "type": "object",
        "required": ["rung", "offset_days", "scheduled_date", "recipients", "days_overdue_on_send", "invoice_attached", "mentions_fee_or_consequence", "mentions_legal_action"],
        "properties": {
          "rung": {"type": "string", "enum": ["polite", "firm", "legal"]},
          "offset_days": {"type": "integer", "enum": [3, 10, 30]},
          "scheduled_date": {"type": "string", "pattern": "^\\d{4}-\\d{2}-\\d{2}$"},
          "recipients": {"type": "array", "minItems": 1, "items": {"type": "string", "pattern": "^[^@\\s]+@[^@\\s]+$"}},
          "days_overdue_on_send": {"type": "integer", "minimum": 3},
          "invoice_attached": {"const": true},
          "mentions_fee_or_consequence": {"type": "boolean"},
          "mentions_legal_action": {"type": "boolean"},
          "word_count": {"type": "integer", "minimum": 1},
          "asks_confirmed_payment_date": {"type": "boolean"},
          "pay_by_date": {"type": "string", "pattern": "^\\d{4}-\\d{2}-\\d{2}$"},
          "pay_by_within_days": {"type": "integer", "minimum": 1, "maximum": 7},
          "consequence_reference": {"type": "string", "minLength": 5},
          "ledger_total_with_interest": {"type": "number", "exclusiveMinimum": 0},
          "final_deadline_days": {"type": "integer", "minimum": 7, "maximum": 14},
          "next_step": {"type": "string", "enum": ["collections_agency", "small_claims", "county_court_claim", "statutory_demand"]},
          "without_prejudice": {"type": "boolean"},
          "channels": {"type": "array", "minItems": 1, "items": {"type": "string", "enum": ["email", "registered_post", "courier"]}}
        },
        "allOf": [
          {"if": {"properties": {"rung": {"const": "polite"}}},
           "then": {"required": ["word_count", "asks_confirmed_payment_date"],
                    "properties": {"offset_days": {"const": 3}, "word_count": {"maximum": 120}, "asks_confirmed_payment_date": {"const": true}, "mentions_fee_or_consequence": {"const": false}, "mentions_legal_action": {"const": false}}}},
          {"if": {"properties": {"rung": {"const": "firm"}}},
           "then": {"required": ["pay_by_date", "pay_by_within_days", "consequence_reference"],
                    "properties": {"offset_days": {"const": 10}, "recipients": {"minItems": 2}, "mentions_fee_or_consequence": {"const": true}, "mentions_legal_action": {"const": false}}}},
          {"if": {"properties": {"rung": {"const": "legal"}}},
           "then": {"required": ["ledger_total_with_interest", "final_deadline_days", "next_step", "without_prejudice", "channels"],
                    "properties": {"offset_days": {"const": 30}, "without_prejudice": {"const": true}, "mentions_legal_action": {"const": true}}}}
        ]
      }
    },
    "status": {
      "type": "object",
      "required": ["payment_status", "dispute_raised", "outstanding_balance", "halted"],
      "properties": {
        "payment_status": {"type": "string", "enum": ["unpaid", "partial", "paid_in_full"]},
        "dispute_raised": {"type": "boolean"},
        "outstanding_balance": {"type": "number", "minimum": 0},
        "halted": {"type": "boolean"},
        "halt_reason": {"type": "string", "enum": ["paid_in_full", "dispute_raised", "ladder_exhausted"]}
      },
      "allOf": [
        {"if": {"properties": {"halted": {"const": true}}}, "then": {"required": ["halt_reason"]}},
        {"if": {"properties": {"payment_status": {"const": "paid_in_full"}}}, "then": {"properties": {"halted": {"const": true}, "outstanding_balance": {"const": 0}}}},
        {"if": {"properties": {"dispute_raised": {"const": true}}}, "then": {"properties": {"halted": {"const": true}}}}
      ]
    },
    "send_log": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["invoice_id", "rung", "send_date", "channel", "recipients", "response"],
        "properties": {
          "invoice_id": {"type": "string", "minLength": 1},
          "rung": {"type": "string", "enum": ["polite", "firm", "legal"]},
          "send_date": {"type": "string", "pattern": "^\\d{4}-\\d{2}-\\d{2}$"},
          "channel": {"type": "string", "enum": ["email", "registered_post", "courier"]},
          "recipients": {"type": "array", "minItems": 1, "items": {"type": "string"}},
          "response": {
            "oneOf": [
              {"const": "none"},
              {"type": "object", "required": ["date", "gist"], "properties": {"date": {"type": "string", "pattern": "^\\d{4}-\\d{2}-\\d{2}$"}, "gist": {"type": "string", "minLength": 5}}}
            ]
          }
        }
      }
    },
    "days_to_pay": {"type": ["integer", "null"], "minimum": 0},
    "renewal_terms_change": {"type": "string", "enum": ["shorter_net_terms", "deposit", "milestone_billing", "none", "pending_renewal"]}
  }
}

