{
  "invoice": {
    "invoice_id": "2026-041",
    "amount": 4800,
    "currency": "GBP",
    "invoice_date": "2026-05-31",
    "due_date": "2026-06-15",
    "payment_terms_clause_id": "MSA 7.2 (net 15)",
    "invoice_link": "https://invoices.faion.example/2026-041.pdf"
  },
  "parties": {
    "freelancer": {"legal_name": "Ruslan Faion", "address": "12 Example Road, Lisbon 1000-001, Portugal"},
    "client": {"legal_name": "Acme Analytics Ltd", "address": "1 Acme Way, London EC1A 1AA, United Kingdom", "sponsor_contact": "dana@acme.example", "finance_contact": "ap@acme.example"}
  },
  "contract": {
    "written_notice_channel": "email_and_registered_post",
    "late_payment_basis": {"kind": "statute", "reference": "Late Payment of Commercial Debts (Interest) Act 1998", "rate": "8% over Bank of England base rate plus GBP 70 fixed compensation", "fixed_fee": 70},
    "legal_handoff_contact": "collections@smallclaimsdesk.example"
  },
  "rungs": [
    {"rung": "polite", "offset_days": 3, "scheduled_date": "2026-06-18", "recipients": ["dana@acme.example"], "days_overdue_on_send": 3, "invoice_attached": true, "mentions_fee_or_consequence": false, "mentions_legal_action": false, "word_count": 84, "asks_confirmed_payment_date": true},
    {"rung": "firm", "offset_days": 10, "scheduled_date": "2026-06-25", "recipients": ["dana@acme.example", "ap@acme.example"], "days_overdue_on_send": 10, "invoice_attached": true, "mentions_fee_or_consequence": true, "mentions_legal_action": false, "pay_by_date": "2026-07-01", "pay_by_within_days": 6, "consequence_reference": "Statutory interest under the Late Payment of Commercial Debts (Interest) Act 1998 at 8% over base rate from 2026-06-16"},
    {"rung": "legal", "offset_days": 30, "scheduled_date": "2026-07-15", "recipients": ["dana@acme.example", "ap@acme.example"], "days_overdue_on_send": 30, "invoice_attached": true, "mentions_fee_or_consequence": true, "mentions_legal_action": true, "ledger_total_with_interest": 4921.4, "final_deadline_days": 14, "next_step": "county_court_claim", "without_prejudice": true, "channels": ["email", "registered_post"]}
  ],
  "status": {"payment_status": "paid_in_full", "dispute_raised": false, "outstanding_balance": 0, "halted": true, "halt_reason": "paid_in_full"},
  "send_log": [
    {"invoice_id": "2026-041", "rung": "polite", "send_date": "2026-06-18", "channel": "email", "recipients": ["dana@acme.example"], "response": {"date": "2026-06-19", "gist": "Sorry, stuck in approvals; will be paid this week"}}
  ],
  "days_to_pay": 20,
  "renewal_terms_change": "deposit"
}

